questionvariables.text:
cosd(x) := cos(x*%pi/180);
sind(x) := sin(x*%pi/180);
atand(x) := 180*atan(x)/%pi;
asind(x) := 180*asin(x)/%pi;
two(v) := if v < 10 then sconcat("0", string(v)) else string(v);
hm(m) := block([q], q: mod(m, 1440), sconcat(two(floor(q/60)), ":", two(mod(q, 60))));
dmx(m) := sconcat(string(floor(m/60)), "^\\circ", two(mod(m, 60)), "'");
cosd(x) := float(cos(x*%pi/180)); sind(x) := float(sin(x*%pi/180));
atand(x) := float(180*atan(x)/%pi); asind(x) := float(180*asin(x)/%pi);
r1(x) := float(floor(10*x+1/2)/10);
clr(x, L) := every(lambda([y], is(abs(x-y)>0.2)), L);
/* Design: resultant velocity at a general angle, by the cosine and sine rules. wt is the direction the wind blows towards. Generic-wrong offsets change sign on a variant where +offset lands near a diagnostic. Source: adapted from SMP Book 5 (Metric), chapter 2, Exercise B question 6. */
c: 15*rand(24);
v: rand_with_step(120,240,20);
u: rand_with_step(20,60,10);
rel: rand([30,40,50,60,70,110,120,130,140,150])*rand([1,-1]);
wt: mod(c+rel,360);
w: mod(wt+180,360);
brg(x,y) := mod(float(180*atan2(x,y)/%pi),360);
Ec: v*sind(c)+u*sind(wt); Nc: v*cosd(c)+u*cosd(wt);
gs: sqrt(Ec^2+Nc^2);
tr: brg(Ec,Nc);
sg: signum(mod(tr-c+180,360)-180);
dr: abs(mod(tr-c+180,360)-180);
ang: 180-abs(rel);
/* diagnostics: wind taken as blowing towards w */
Ew: v*sind(c)+u*sind(w); Nw: v*cosd(c)+u*cosd(w);
gsw: sqrt(Ew^2+Nw^2);
trw: brg(Ew,Nw);
drw: abs(mod(trw-c+180,360)-180);
pp: sqrt(v^2+u^2); sm: v+u;
ws: mod(2*c-tr,360);
o1: if clr(r1(gs)+1.5,[gsw,pp,sm]) then 1 else -1;
o2: if clr(r1(dr)+3,[drw]) then 1 else -1;
o3: if clr(r1(tr)+5,[trw,ws,mod(c+sg*(r1(dr)+3*o2),360)]) then 1 else -1;
g1: r1(gs)+15*(if clr(r1(gs)+15,[gsw,pp,sm]) then 1 else -1);
fd: asind(u*sind(abs(rel))/g1);
ra: r1(dr)+3*o2;

feedbackvariables.text:
ym: asind(u/v);
q: if ans1>0 then u*sind(abs(rel))/ans1 else 2;
ft2: is(abs(ans1-gs)>0.0501 and q<=1 and abs(ans2-asind(q))<=0.0501);
